pub fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    assert!(
        s2.len() == n && s3.len() == n,
        "All input vectors must have the same length"
    );

    let cap = n.checked_mul(3).expect("Capacity overflow computing 3*n");
    let mut res = Vec::with_capacity(cap);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}